<div class="page-head"><div><h1><?= te('Recruitment and onboarding') ?></h1></div></div>
<?php if($inviteUrl): ?><div class="card"><h2><?= te('Private invitation · expires in 48 hours') ?></h2><p><?= te('Send this link directly to the candidate through your approved communication channel.') ?></p><input readonly value="<?= e($inviteUrl) ?>"></div><?php endif; ?>
<div class="grid g2"><form method="post" class="card"><?= csrf_field() ?><input type="hidden" name="do" value="invite"><h2><?= te('Invite candidate to private portal') ?></h2><p class="small muted m0 pull-up mb"><?= te('They get a link to sign in, see their offer, their tasks and their travel.') ?></p><label for="inv-who"><?= te('Who') ?></label><select id="inv-who" name="candidate_id" required><option value=""><?= te('Choose somebody…') ?></option><?php foreach($people as $person): ?><option value="<?= (int)$person['id'] ?>"><?= e($person['full_name']) ?><?php if($person['city']): ?> &middot; <?= e(trim($person['city'].' '.$person['state'])) ?><?php endif; ?></option><?php endforeach; ?></select><button class="btn"><?= te('Generate invitation') ?></button></form>
<form method="post" class="card"><?= csrf_field() ?><input type="hidden" name="do" value="requirement"><h2><?= te('Add project requirement') ?></h2><label><?= te('Task name') ?></label><input name="title" maxlength="190" required><label><?= te('Instructions / approved provider link') ?></label><textarea name="instructions"></textarea><label><?= te('Form filled in the task') ?></label><select name="form_kind"><option value=""><?= te('None: the worker answers with a note') ?></option><option value="w4"><?= te('Form W-4, filled in and signed in the portal') ?></option><option value="i9"><?= te('Form I-9 Section 1, filled in and signed in the portal') ?></option><option value="bank"><?= te('Direct deposit: bank details with a proof') ?></option></select><label><input class="w-auto" type="checkbox" name="for_crew"> <?= te('Also ask the crew already on site') ?></label><p class="small muted"><?= te('Every new hire on this project gets it as a task. The crew already working here gets it only if you tick the box (a new safety rule, for instance).') ?></p><p class="small muted"><?= te('A W-4, an I-9 or direct deposit: choose the form, and the worker fills it in the task itself, the numbers masked and encrypted; payroll or the office checks it on Change requests, and the task closes by itself.') ?></p><button class="btn"><?= te('Add requirement') ?></button></form></div>
<div class="card"><h2><?= te('Worker tasks') ?></h2><?php $obWord = ['pending' => t('Waiting for the worker'), 'submitted' => t('Submitted, to review'), 'approved' => t('Approved'), 'rejected' => t('Sent back to the worker')]; ?><?php foreach($tasks as $t): ?><div class="row list-row" data-task="<?= (int)$t['id'] ?>" data-status="<?= e($t['status']) ?>"><span><strong><?= e($t['full_name']) ?></strong> · <?= e($t['title']) ?> · <span class="tag <?= $t['status'] === 'approved' ? 'green' : ($t['status'] === 'submitted' ? 'amber' : 'grey') ?>"><?= e($obWord[$t['status']] ?? $t['status']) ?></span></span><?php if ((string) $t['response'] !== ''): ?><span class="small"><?= e($t['response']) ?></span><?php endif; ?><?php if ($t['status'] === 'submitted' && ! empty($t['form_kind'])): ?><a class="small" href="/change-requests#tax-forms"><?= te('Closes with its form, on Change requests') ?></a><?php elseif ($t['status'] === 'submitted'): ?><form class="row" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="review"><input type="hidden" name="task_id" value="<?= (int)$t['id'] ?>"><select name="status" aria-label="<?= te('Decision') ?>"><option value="approved"><?= te('Approve') ?></option><option value="rejected"><?= te('Send back') ?></option></select><button class="btn sm"><?= te('Review') ?></button></form><?php endif; ?></div><?php endforeach; ?></div>
<div class="card"><h2><?= te('Application QR codes') ?></h2><p><?= te('Create and manage requisitions in your recruiting workspace.') ?></p><a class="btn" href="/requisitions"><?= te('Open requisitions') ?></a></div>
<div class="card tight"><div class="card-bar"><h2 class="m0"><?= te('Applications on this project') ?></h2><p class="small muted m0 mt-xs"><?= te('Invite somebody above once they have an offer, so they can see it and work their tasks.') ?></p></div><?php if(!$applications): ?><div class="empty"><?= te('No applications on this project yet.') ?></div><?php else: ?><?php $appWords = ['new'=>'New','screening'=>'Screening','interview'=>'Interview','offered'=>'Offered','accepted'=>'Accepted','rejected'=>'Rejected','withdrawn'=>'Withdrawn']; ?><div class="scroll"><table><thead><tr><th><?= te('Person') ?></th><th><?= te('Applied for') ?></th><th><?= te('Stage') ?></th></tr></thead><tbody><?php foreach($applications as $a): ?><tr><td><a href="/candidates/<?= (int)$a['candidate_id'] ?>"><?= e($a['full_name']) ?></a></td><td class="small"><?= e($a['title']) ?></td><td><span class="tag <?= in_array($a['stage'],['accepted'],true)?'green':(in_array($a['stage'],['rejected','withdrawn'],true)?'red':(in_array($a['stage'],['offered','interview'],true)?'amber':'grey')) ?>"><?= te($appWords[$a['stage']] ?? $a['stage']) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>

<div class="card"><h2><?= te('Configure project instructions') ?></h2><?php foreach($requirements as $requirement): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="do" value="configure_requirement"><input type="hidden" name="requirement_id" value="<?= (int)$requirement['id'] ?>"><h3><?= e($requirement['title']) ?></h3><label><?= te('Approved instructions') ?><textarea name="instructions" required maxlength="8000"><?= e($requirement['instructions']) ?></textarea></label><label><?= te('Form filled in the task') ?></label><select name="form_kind"><?php foreach (['' => t('None: the worker answers with a note'), 'w4' => t('Form W-4, filled in and signed in the portal'), 'i9' => t('Form I-9 Section 1, filled in and signed in the portal'), 'bank' => t('Direct deposit: bank details with a proof')] as $k => $label): ?><option value="<?= e($k) ?>" <?= (string) ($requirement['form_kind'] ?? '') === $k ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select><label><input class="w-auto" name="required" type="checkbox" <?= $requirement['required']?'checked':'' ?>> <?= te('Required') ?></label><label><input class="w-auto" name="for_crew" type="checkbox" <?= $requirement['for_crew']?'checked':'' ?>> <?= te('Also ask the crew already on site') ?></label><button class="btn ghost"><?= te('Save instructions') ?></button></form><?php if (onboarding_requirement_removable((int) $requirement['id'])): ?><form method="post" class="mb" data-remove-requirement="<?= (int) $requirement['id'] ?>" onsubmit="return confirm(<?= e(json_encode(t('Remove this requirement? Nobody has answered it yet.'), JSON_UNESCAPED_UNICODE)) ?>)"><?= csrf_field() ?><input type="hidden" name="do" value="remove_requirement"><input type="hidden" name="requirement_id" value="<?= (int) $requirement['id'] ?>"><button class="btn ghost sm"><?= te('Remove this requirement') ?></button></form><?php endif; ?><?php endforeach; ?></div>
